    public void testBlanksNode() {
        Node node = Jsoup.parse("<node>text</node>").body().children().first();
        assertFalse(node.isBlank());
    }

    @Test
    public void testCloneText() {
        Document document = new Document("").create();
        String text = "text";
        String clonedText = document.cloneText(text);
        assertEquals(text, clonedText);
    }
}

